// deterministic scatter: flowers + rocks + small tufts markers
const SCATTER: Prop[] = [];
// step 5 across the grid used to cover 4% of the world once the map grew, so
// flowers and rocks only appeared in the old town. 7 keeps the scatter broad
// without turning the countryside into confetti.
for (let gx = 3; gx < Pe - 2; gx += 7) {
  for (let gy = 3; gy < vt - 2; gy += 7) {
    const r = h2(gx * 3 + 11, gy * 9 + 7);
    if (r > 0.16) continue;
    const tx = gx + Math.floor(h2(gx, gy + 1) * 3);
    const ty = gy + Math.floor(h2(gy, gx + 2) * 3);
    if (!natureFree(tx, ty)) continue;
    // wildflowers and rocks belong to the field and the parks, not to a paved
    // lot - same rule as the grass tufts in drawTerrainDecor
    if (PAVED[ty * Pe + tx]) continue;
    const kind = r < 0.07 ? "flower" : "rock";
    SCATTER.push({ kind, x: tx * V + 6, y: ty * V + 12, seed: h2(tx + 5, ty + 6) });
  }
}

